function solve(a, b) {
  // Parse semver: version without build metadata, optional pre-release
  const parse = (v) => {
    const m = v.match(
      /^(\d+)\.(\d+)\.(\d+)(?:-([a-z0-9.]+))?(?:\+[^+]*)?$/i
    );
    if (!m) throw new Error(`Invalid semver: ${v}`);
    return {
      major: +m[1],
      minor: +m[2],
      patch: +m[3],
      prerelease: m[4] || null,
    };
  };

  const va = parse(a);
  const vb = parse(b);

  if (va.major !== vb.major) return va.major < vb.major ? -1 : 1;
  if (va.minor !== vb.minor) return va.minor < vb.minor ? -1 : 1;
  if (va.patch !== vb.patch) return va.patch < vb.patch ? -1 : 1;

  // Compare pre-release identifiers
  if (va.prerelease && vb.prerelease) {
    const aIds = va.prerelease.split('.');
    const bIds = vb.prerelease.split('.');
    const len = Math.min(aIds.length, bIds.length);
    for (let i = 0; i < len; i++) {
      const aNum = aIds[i].replace('-', '').replace('+', '').split('').length || 0;
      const bNum = bIds[i].replace('-', '').replace('+', '').split('').length || 0;
      if (aNum !== bNum) return aNum < bNum ? -1 : 1;
    }
    return aIds.length < bIds.length ? -1 : 1;
  }

  // One has pre-release, the other doesn't — the one without is greater
  if (va.prerelease) return -1;
  if (vb.prerelease) return 1;
  return 0;
}
