  if (n <= 1) return 0;

  // Max profit with at most 1 transaction up to day i
  let minPrice = precos[0];
  const left = new Array(n).fill(0);
  for (let i = 1; i < n; i++) {
    minPrice = Math.min(minPrice, precos[i]);
    left[i] = Math.max(left[i - 1], precos[i] - minPrice);
  }

  // Max profit with at most 1 transaction from day i to end
  let maxPrice = precos[n - 1];
  const right = new Array(n).fill(0);
  for (let i = n - 2; i >= 0; i--) {
    maxPrice = Math.max(maxPrice, precos[i]);
    right[i] = Math.max(right[i + 1], maxPrice - precos[i]);
  }

  let maxProfit = 0;
  for (let i = 0; i < n; i++) {
    maxProfit = Math.max(maxProfit, left[i] + right[i]);
  }

  return maxProfit;
}
